import { FilterDataAccessor } from 'domain/Filter/FilterDataAccessor';
import type { FilterDataStructure, FilterForm } from 'models/Filters';

function safeStringLabel(label: unknown): string {
  return typeof label === 'string' ? label : '';
}

export function getPhiCountryScope(
  dataFilters: FilterDataStructure | undefined,
  applied: FilterForm,
  isGlobalZone: boolean,
): string | undefined {
  if (isGlobalZone || applied.country === 'ABI') {
    return undefined;
  }

  const country = FilterDataAccessor.getInstance().getCountry(
    dataFilters ?? {},
    applied,
  );

  const label = safeStringLabel(country?.label);
  return label || undefined;
}
